    "title": "Regra — carryServerRoutes",
    "content": "O editor do guia regrava a lista inteira a cada salvamento. A distância que vem do aparelho NUNCA é marcada\ncomo trajeto (`distance_kind` fica nulo); para o mesmo lugar (scope + place_id) que o servidor já tinha\nconfirmado por rota, a medição do servidor é mantida no lugar da do aparelho.",
