    "kind": "rule",
    "title": "Regra — CleaningAdvanceDecision",
    "content": "Conclusão da limpeza (07/11/2026): a janela \"Qual limpeza foi feita?\" só\nabre quando o imóvel tem os DOIS tipos cadastrados (normal e completa).\nCom um só tipo, conclui direto nele; sem nenhum, conclui sem tipo — nada de\njanela com um botão solitário.",
    "source_path": "src/lib/cleaning-advance.ts",
