    "kind": "rule",
    "title": "Regra — CleaningInlineEditor",
    "content": "Bloco \"Limpeza\" dentro da janela de detalhes do card.\n 09/11/2026 (mockup aprovado): só aparece o que já está confirmado — Prestador e o botão verde \"Finalizar Limpeza\"\n (largura toda). Tipo e Valor ainda não foram confirmados (só se definem ao finalizar) e o quadrado \"Limpeza não\n será realizada\" saiu daqui; os dois continuam no menu do card (Ajustar valor / Limpeza não será realizada).",
