    "content": "Recorta o trecho do \"CONTRATANTE\" — do rótulo até o próximo bloco\n(CONTRATADA/CONTRATADO, cláusula, objeto…). Se não achar, devolve o\ninício da página para a IA analisar mesmo assim.",
