    "content": "Contexto autorizado de um turno. `guest.credentials` é SEMPRE `null` (o Orchestrator recusa\nqualquer outro valor). Histórico e posse humana detalhada chegam na B2; aqui o contrato já existe.",
    "source_path": "src/lib/guest-ai/orchestrator/contracts.ts",
