    "kind": "rule",
    "title": "Regra — createCardSetupIntent",
    "content": "Janela de cartão dentro do sistema (Stripe Elements): prepara o cadastro do cartão da conta.\nServe para conta isenta, conta paga e troca depois de pagamento recusado.",
