    "content": "Afirmação EXPLÍCITA de confirmação do marco (fato consumado). Autorização/liberação/antecipação NÃO conta:\n\"check-in autorizado\" ≠ \"check-in confirmado\". Frases indiretas ficam com o modelo.",
