    "title": "Regra — fallbackModel",
    "content": "RACIOCÍNIO ELÁSTICO NATIVO (ajuste fino do PR #11): não há tabela de esforço por tarefa. Nenhuma chamada\nconvencional fixa `reasoning_effort`; o modelo dosa sozinho (`auto`). Custo contido pelos tetos de cada rota.",
