    "doc_key": "rule:filterUpcoming",
    "kind": "rule",
    "title": "Regra — filterUpcoming",
    "content": "Regra de ouro do calendário: nada que já aconteceu chega ao hóspede, e nada distante demais.\n- Itens de categoria \"evento\" só passam com data confirmada.\n- Um evento é válido enquanto (endDate ?? startDate) >= hoje e começa até hoje + janela.\n- Itens perenes (restaurante, passeio, natureza…) não têm data e seguem válidos.",
    "source_path": "src/lib/city-news-window.ts",
