    "kind": "rule",
    "title": "Regra — getConnectedListingsInventory",
    "content": "Inventário de anúncios conectados ativos da conta — a mesma lista que a Stripe cobra\n(`loadConnectedListings`). Gêmeos contam individualmente. Sempre derivado do banco.",
