    "title": "Regra — hasPendingDecision",
    "content": "Há decisão PENDENTE que ainda cala a IA nesta conversa? Só se foi aberta há menos de 2 h E nenhum atendente\nhumano falou com o hóspede depois dela (fala humana = pendência tratada; a IA volta nas mensagens seguintes).\nO cartão continua no painel até alguém decidir; só deixa de bloquear a IA. Falha de leitura ⇒ não bloqueia.",
    "source_path": "src/lib/guest-ai-decision.server.ts",
