    "title": "Regra — isSatisfiedCheckReply",
    "content": "Resposta de SATISFAÇÃO à checagem (\"Encontramos sim. Um apartamento muito bonito.\", caso Jenifer 11/11/2026):\nafirma que está tudo bem, sem pergunta, pedido, horário, ressalva ou relato de problema. Na dúvida ⇒ não.",
