    "content": "Emite a concessão. Recusa (lança) se o resultado não for `allow`, se o turno\nnão for um `ValidatedTurn` emitido pelo módulo de dados, ou se a reserva não\nfor a vinculada ao turno.",
    "source_path": "src/lib/guest-ai/policy/grants.ts",
