    "content": "Chamado DEPOIS que a equipe marca a conversa como resolvida. Só considera \"incidente resolvido pela\nequipe\" quando a equipe de fato atuou (houve encaminhamento ou alguém assumiu). Imóvel lido da própria\nconversa no banco. Nunca lança.",
