    "doc_key": "rule:learningThemeKey",
    "kind": "rule",
    "title": "Regra — learningThemeKey",
    "content": "TEMA de um fato: categoria + os DOIS primeiros termos de conteúdo (sem acento, minúsculas; termos com hífen\nficam inteiros: \"ar-condicionado\", \"wi-fi\"). Ex.: \"O Wi-Fi da varanda depende do repetidor\" e \"O Wi-Fi da\nvaranda agora usa o roteador novo\" ⇒ mesmo tema (equipamentos · wi-fi varanda). Regra simples e previsível;\ndois fatos distintos sobre o mesmo objeto e o mesmo cômodo contam como o mesmo tema.",
