    "content": "Portfólio (12/11/2026, sugestão de outro imóvel do anfitrião): só identificação pública e link do anúncio.\nDas configurações do anúncio, SÓ a regra de disponibilidade (mínimo de noites, horizonte), por caminho JSON:\nnada de mensagem de boas-vindas, preços, taxas ou dados de conta.",
