    "title": "Regra — RESERVATION_WAIT_MAX_MS",
    "content": "Espera curta pela reserva que a Channex já indicou na conversa mas que ainda não chegou ao banco (corrida\nentre o webhook da mensagem e o da reserva; caso Karen, 10/11/2026: 19 s de diferença). Consulta só o banco,\na cada `stepMs`, até `maxMs`. Nunca lança.",
