    "title": "Regra — resolvePropertyTimezone",
    "content": "`explicit` (coluna futura) tem precedência, mas precisa ser IANA válida e, havendo derivação\nresolvida, coincidir com ela; divergência ⇒ conflito ⇒ não resolvido.",
    "source_path": "src/lib/guest-ai/policy/timezone-source.ts",
