    "content": "ABA \"FINANCEIRO\" DA FICHA DO PROPRIETÁRIO (mockup P3).\n\nLançamentos a receber / a pagar deste proprietário. Os três totais do topo\nsomam os lançamentos (sem centavos, sempre arredondados para cima).",
